{"code":"func (s *Server) DeleteHandler(c *gin.Context) {
	var r api.DeleteRequest
	if err := c.ShouldBindJSON(&r); errors.Is(err, io.EOF) {
		c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "missing request body"})
		return
	} else if err != nil {
		c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}","desc":"DeleteHandler 是调用链从路由分发流入实际处理逻辑的 callee 入口，函数体通过 c.ShouldBindJSON 完成请求体格式合法性校验，确认 model 字段存在后即向下继续执行，全程未对调用方身份进行鉴权。随后控制流传递至模型查找与删除逻辑，这一函数体构成了从 HTTP 路由层到存储操作层的过渡节点，是权限缺失穿透至破坏性操作的关键中间跳。","file":"server/routes.go","line":"982-990"}

{"code":"	if err := m.Remove(); err != nil {
