		restrictedPaths.some((restrictedPath) => isContainedWithin(restrictedPath, resolvedFilePath))
	) {
		return true;
	}","desc":"isFilePathBlocked 在文件流创建前检查路径是否命中受限列表，默认配置下仅封堵 .n8n 目录，/etc、~/.ssh 等敏感路径均可通过。作为文件访问的唯一防护门，该函数覆盖范围严重不足，无法阻止用户脚本经由 createReadStream 或 writeContentToFile 访问宿主机上的任意敏感路径。","file":"packages/core/src/execution-engine/node-execution-context/utils/file-system-helper-functions.ts","line":"75-84"}

